# -*- coding: utf-8 -*-
import streamlit as st
import streamlit.components.v1 as components

APP_HTML = '<!doctype html>\n<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;padding:0;width:100%;height:100%;background:#f4f7f5;overflow:hidden}.view{display:none;width:100%;height:1500px;border:0}.view.active{display:block}</style></head><body>\n<iframe id="dashFrame" class="view active" sandbox="allow-scripts allow-forms allow-modals allow-same-origin allow-popups"></iframe>\n<iframe id="manageFrame" class="view" sandbox="allow-scripts allow-forms allow-modals allow-same-origin allow-popups"></iframe>\n<script>\nconst dash=document.getElementById(\'dashFrame\'),manage=document.getElementById(\'manageFrame\');\nfunction decodeHtml(b64){const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));return new TextDecoder(\'utf-8\').decode(bytes)}\ndash.srcdoc=decodeHtml(\'\');manage.srcdoc=decodeHtml(\'\');\nfunction show(page){const m=page===\'manage\';dash.classList.toggle(\'active\',!m);manage.classList.toggle(\'active\',m);window.scrollTo(0,0)}\nwindow.addEventListener(\'message\',e=>{if(e.data&&e.data.type===\'mg-nav\')show(e.data.page)});\n</script></body></html>'

st.set_page_config(page_title="MG 금융 데이터", layout="wide", initial_sidebar_state="collapsed")
st.markdown("""
<style>
.block-container {padding:0; max-width:100%;}
header[data-testid="stHeader"] {background:transparent;}
</style>
""", unsafe_allow_html=True)
components.html(APP_HTML, height=1500, scrolling=False)
